SCRIPT = r'''document.addEventListener('DOMContentLoaded', function(){
  const nav = document.querySelector('.site-nav');
  const hamburger = document.querySelector('.nav-hamburger');
  const menu = document.querySelector('.mobile-menu');
  const onScroll = () => nav && nav.classList.toggle('scrolled', window.scrollY > 40);
  onScroll(); window.addEventListener('scroll', onScroll);
  if (hamburger && menu) {
    hamburger.addEventListener('click', () => { hamburger.classList.toggle('open'); menu.classList.toggle('open'); document.body.style.overflow = menu.classList.contains('open') ? 'hidden' : ''; });
    menu.querySelectorAll('a').forEach(a => a.addEventListener('click', () => { hamburger.classList.remove('open'); menu.classList.remove('open'); document.body.style.overflow = ''; }));
  }
  const reveals = document.querySelectorAll('.reveal');
  const observer = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); observer.unobserve(e.target); } }); }, {threshold:.1, rootMargin:'0px 0px -40px 0px'});
  reveals.forEach(el=>observer.observe(el));
});'''

NAV_ITEMS = [
    ('Home', 'index.html'),
    ('About Us', 'about.html'),
    ('Services', 'services.html'),
    ('Quality', 'quality.html'),
    ('Contact', 'contact.html'),
]

def nav(active):
    links = ''.join(f'<li><a class="{ "active" if label == active else "" }" href="{href}">{label}</a></li>' for label, href in NAV_ITEMS)
    mobile = ''.join(f'<a href="{href}">{label}</a>' for label, href in NAV_ITEMS)
    return f'''<nav class="site-nav"><a class="nav-logo" href="index.html"><img src="images/jourthon_logo_color.webp" alt="Jourthon Nutrition"></a><ul class="nav-links">{links}</ul><div class="nav-cta"><a class="btn-primary-nav" href="contact.html#inquiry">Project Inquiry</a></div><button class="nav-hamburger" aria-label="Open menu"><span></span><span></span><span></span></button></nav><div class="mobile-menu">{mobile}<a class="btn-primary btn-mobile" href="contact.html#inquiry">Project Inquiry</a></div>'''

def footer():
    return '''<footer><div class="container"><div class="footer-grid"><div><a class="footer-logo" href="index.html"><img src="images/jourthon_logo_white.webp" alt="Jourthon Nutrition"></a><p class="footer-desc">North America's full-chain health supplement launch partner. From formula to shelf, Jourthon helps global wellness brands build compliant, market-ready products.</p></div><div><div class="footer-title">Solutions</div><ul class="footer-links"><li><a href="services.html#launch">New Brand Launch</a></li><li><a href="services.html#compliance">Compliance Fast Track</a></li><li><a href="services.html#manufacturing">Private Label Manufacturing</a></li><li><a href="services.html#market">Market Entry Support</a></li></ul></div><div><div class="footer-title">Company</div><ul class="footer-links"><li><a href="about.html">About Us</a></li><li><a href="quality.html">Quality Standards</a></li><li><a href="services.html">Services</a></li><li><a href="contact.html">Contact</a></li></ul></div><div><div class="footer-title">Contact</div><ul class="footer-links"><li><a href="mailto:info@jourthon.online">info@jourthon.online</a></li><li><a href="contact.html#inquiry">Submit Product Brief</a></li><li><a href="contact.html">Partner With Us</a></li></ul></div></div><div class="footer-bottom"><div>© 2026 Jourthon Nutrition Inc. All rights reserved. Incorporated in Canada.</div><div>Privacy Policy · Terms of Service</div></div></div></footer>'''

